fn main() {
    let builder = ezcount_lib::create_specta_builder();
    let out_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../src/bindings.ts");
    let content = builder
        .export_str(
            specta_typescript::Typescript::default()
                .bigint(specta_typescript::BigIntExportBehavior::Number),
        )
        .expect("Failed to export typescript bindings");

    let formatted = format!(
        "// @ts-nocheck\n// Auto-generated by tauri-specta. Do not edit manually.\n{}",
        content
    );
    std::fs::write(&out_path, formatted).expect("Failed to write bindings.ts");
    println!("Successfully exported TypeScript bindings to src/bindings.ts");
}
